#!/usr/bin/env bash
# Regenerates Cargo.toml so every lesson file is a runnable example.
# Lesson NN in chapter-CC-* becomes `cargo run --example chCC-NN`.
set -euo pipefail
cd "$(dirname "$0")/.."
{
cat <<'HEAD'
# Generated by scripts/gen-cargo-toml.sh. Each lesson is an example:
#   cargo run --example ch01-01
[package]
name = "rust199"
version = "1.0.0"
edition = "2021"
publish = false
description = "Code for the book Rust in 199 Pages"
autoexamples = false

[workspace]
members = [".", "projects/*"]

[lib]
path = "lib.rs"

[dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = "1"
HEAD
for f in chapter-*/[0-9][0-9]-*.rs chapter-*/[0-9][0-9]-*/main.rs; do
  [ -e "$f" ] || continue
  ch=$(echo "$f" | sed -E 's#chapter-([0-9]+)-.*#\1#')
  ls=$(echo "$f" | sed -E 's#chapter-[0-9]+-[^/]+/([0-9]+)-.*#\1#')
  printf '\n[[example]]\nname = "ch%s-%s"\npath = "%s"\n' "$ch" "$ls" "$f"
done
} > Cargo.toml
